public with sharing class ContactPhoneCleanup {
    /**
     * Returns a map from Contact Id to the first DML error message for contacts
     * whose Phone cleanup could not be saved.
     *
     * A small change from "update every contact that has a phone": a phone value
     * is only added to the update list when the cleaned value differs from the
     * original. This preserves the single partial DML call while avoiding
     * unnecessary record updates, trigger/Flow work, and validation errors for
     * records that were already clean. Remove the "if (cleanedPhone != ...)" guard
     * if every phone record must be attempted, even when unchanged.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errorsByContactId = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return errorsByContactId;
        }

        List<Contact> contacts = new List<Contact>();

        for (Contact contactRecord : [SELECT Id, Phone FROM Contact WHERE Id IN :contactIds]) {
            if (String.isNotBlank(contactRecord.Phone)) {
                String cleanedPhone = contactRecord.Phone.replaceAll('[^0-9+]', '');

                if (cleanedPhone != contactRecord.Phone) {
                    contactRecord.Phone = cleanedPhone;
                    contacts.add(contactRecord);
                }
            }
        }

        if (contacts.isEmpty()) {
            return errorsByContactId;
        }

        Database.SaveResult[] saveResults = Database.update(contacts, false);

        for (Integer i = 0; i < saveResults.size(); i++) {
            Database.SaveResult result = saveResults[i];

            if (!result.isSuccess()) {
                String firstErrorMessage = '';
                if (!result.getErrors().isEmpty()) {
                    firstErrorMessage = result.getErrors()[0].getMessage();
                }

                if (firstErrorMessage == null) {
                    firstErrorMessage = '';
                }

                errorsByContactId.put(contacts[i].Id, firstErrorMessage);
            }
        }

        return errorsByContactId;
    }
}
