public with sharing class CasePriorityHandler {

    public static void handleBeforeInsert(List<Case> newCases) {

        // 1. Collect the Account Ids we need to look up (skip nulls).
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        // 2. One query for the whole batch instead of one-per-row.
        //    Governor limit is 100 SOQL per transaction; 200 rows inside
        //    a loop would exceed it, so we stay outside the loop.
        Map<Id, Account> accountMap = new Map<Id, Account>(
            [SELECT Id, Rating FROM Account WHERE Id IN :accountIds]
        );

        // 3. Walk the cases again and bump Priority where the account is Hot.
        for (Case c : newCases) {
            if (c.AccountId != null) {
                Account acc = accountMap.get(c.AccountId);
                if (acc != null && acc.Rating == 'Hot') {
                    c.Priority = 'High';
                }
            }
        }
    }
}
