        // transaction, so we chunk into groups of 50 to stay under the cap.
        // Each chunk runs in its own Queueable execution context, giving
        // per-chunk failure isolation.
        final Integer BATCH_SIZE = 50;

        for (Integer i = 0; i < qualifyingIds.size(); i += BATCH_SIZE) {
            Integer endIdx = Math.min(i + BATCH_SIZE, qualifyingIds.size());
            List<Id> chunk = qualifyingIds.subList(i, endIdx);
            System.enqueueJob(new CaseSurveyJob(chunk));
        }
    }
}
